<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {numbersWindow,numbersDocument,numbersSheet,numbersTable,numbersAvailability,NUMBERS_TOOLBAR_GROUPS} from './numbers-state.js';
 import {NUMBERS_TEMPLATES,numbersEvaluation,numbersCellText,numbersVisibleRows,numbersSelection,numbersChart} from './numbers-model.js';
 import {columnName,parseCellReference} from './office-spreadsheet-kernel.js';
 import {numbersMenus} from './numbers-menus.js';
 import {createNumbersNativeView} from './numbers-native-view.js';
 import './numbers.css';
 import {createDocumentFonts} from './document-fonts.svelte.js';
 let {state: numbersState,profile,window,windowId=window?.id,execute,registerView=()=>{},available=true,active=true,controls={},showMenuBar=false,getShared=name=>controls.getShared?.(name),getFile=id=>controls.getFile?.(id)}=$props();
 let root=$state(),message=$state(''),category=$state('All Templates'),saveName=$state(''),exportFormat=$state('xlsx'),chartType=$state('bar'),chartRange=$state('A1:C4'),sortColumn=$state(1),filterValue=$state(''),filterOperator=$state('contains');
 let originalState,originalWindow,originalRoot,originalProfile,originalSession,retired=false;
 const w=$derived(numbersWindow(numbersState,windowId)),d=$derived(numbersDocument(numbersState,w)),sheet=$derived(numbersSheet(d,w)),table=$derived(numbersTable(d,w)),cap=$derived(numbersAvailability(profile)),classic=$derived(/high-sierra|mojave/u.test(profile.id)),highSierra=$derived(profile.id.includes('high-sierra')),gold=$derived(profile.id.includes('golden-gate'));
 const evaluation=$derived(d?numbersEvaluation(d.content):null),selection=$derived(table?numbersSelection(w):null),menus=$derived(numbersMenus({state: numbersState,profile,windowId})),selectedFormat=$derived(table?.cells[w?.selection.focus]?.format??{});
 function current(){return !retired&&root===originalRoot&&root?.isConnected===true&&numbersState===originalState&&window===originalWindow&&profile===originalProfile&&w===originalSession;}
 async function send(suffix,payload={}){if(!current()||!available||!active)return;const r=await execute('numbers.'+suffix,{windowId},payload);if(current())message=r?.status==='rejected'?r.error?.message??'Operation unavailable.':'';return r;}
 async function menu(item){if(!item.enabled||!current())return;const r=await execute(item.request.command,item.request.target,item.request.payload);if(current())message=r?.status==='rejected'?r.error?.message??'Operation unavailable.':'';}
 async function cellClick(t,address,event){if(table!==t){const r=await send('table.select',{tableId:t.id});if(r?.status!=='applied')return;}await send('select',{address,extend:event.shiftKey});}
 async function cellEdit(t,address,event){await cellClick(t,address,event);if(current())await send('edit.begin');}
 async function keyboard(e){if(!current())return;if(w.dialog!=='none'){if(e.key==='Escape'){e.preventDefault();await send('dialog',{dialog:d?'none':'templates'});}return;}if(!table)return;const input=/^(INPUT|SELECT|TEXTAREA)$/u.test(e.target.tagName)||!!e.target.closest('button')&&!e.target.closest('.numbers-table');if(e.metaKey||e.ctrlKey){const map={s:'save',p:'print',n:'window.new',o:'open',z:e.shiftKey?'redo':'undo'};if(map[e.key.toLowerCase()]){e.preventDefault();await send(map[e.key.toLowerCase()]);return;}if(!input&&['c','v','x','a'].includes(e.key.toLowerCase())){e.preventDefault();await send('clipboard',{operation:{c:'copy',v:'paste',x:'cut',a:'selectAll'}[e.key.toLowerCase()]});return;}}if(input)return;const at=parseCellReference(w.selection.focus),moves={ArrowLeft:[0,-1],ArrowRight:[0,1],ArrowUp:[-1,0],ArrowDown:[1,0]};if(moves[e.key]){e.preventDefault();const [r,c]=moves[e.key];await send('select',{address:columnName(Math.max(1,Math.min(table.columns,at.column+c)))+Math.max(1,Math.min(table.rows,at.row+r)),extend:e.shiftKey});}else if(e.key==='Enter'||e.key==='F2'){e.preventDefault();await send('edit.begin');}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();await send('clear');}else if(e.key.length===1&&!e.altKey){e.preventDefault();await send('edit.input',{input:e.key});await tick();await send('focus',{controlId:'cell-editor'});}}
 async function editorKey(e){if(e.key==='Enter'){e.preventDefault();await send('edit.commit');await tick();await send('focus',{controlId:'sheet'});}else if(e.key==='Escape'){e.preventDefault();await send('edit.cancel');}}
 const toolbarIcons={view:'▣',zoom:'⌕',table:'▤',chart:'◔',share:'↥',format:'◩',organize:'≡'};
 const toolbarGroups=$derived(w?.toolbar.items.filter(id=>id!=='organize')??[]);
 function toolbarLabel(id){return id==='organize'?(highSierra?'Sort & Filter':'Organize'):id[0].toUpperCase()+id.slice(1);}
 function toolbarAction(id){if(id==='view')return send('panel',{panel:w.panel==='none'?'format':'none'});if(id==='table')return send('table.add');if(id==='chart')return send('chart.add',{type:chartType,range:chartRange,title:'Chart'});if(id==='share')return send('share');if(id==='format'||id==='organize')return send('panel',{panel:id});}
 let toolbarDragSource=null;
 function toolbarDrag(event,item){if(!current()||w.dialog!=='toolbar')return;toolbarDragSource={root,window,session:w,toolbar:w.toolbar,items:w.toolbar.items,item};event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('application/x-numbers-toolbar',JSON.stringify({windowId,item,revision:numbersState.revision,items:w.toolbar.items.join(',')}));}
 function toolbarOver(event){if(current()&&w.dialog==='toolbar'&&event.dataTransfer.types.includes('application/x-numbers-toolbar'))event.preventDefault();}
 async function toolbarDrop(event,before=null,remove=false){event.preventDefault();if(!current()||w.dialog!=='toolbar')return;try{const source=JSON.parse(event.dataTransfer.getData('application/x-numbers-toolbar')),original=toolbarDragSource;if(!original||original.root!==root||original.window!==window||original.session!==w||original.toolbar!==w.toolbar||original.items!==w.toolbar.items||original.item!==source.item||source.windowId!==windowId||source.revision!==numbersState.revision||source.items!==w.toolbar.items.join(',')||source.item!=='default-set'&&!NUMBERS_TOOLBAR_GROUPS.includes(source.item)){message='The original toolbar drag source changed. Start the drag again.';return;}toolbarDragSource=null;if(source.item==='default-set'){if(remove){message='Drag the default set into the toolbar to restore it.';return;}await send('toolbar.reset');return;}await send(remove?'toolbar.remove':'toolbar.insert',remove?{item:source.item}:{item:source.item,before});}catch{toolbarDragSource=null;message='The original toolbar drag source is unavailable.';}}
 function toolbarMove(item,direction){const index=toolbarGroups.indexOf(item),before=direction<0?toolbarGroups[index-1]:toolbarGroups[index+2]??null;return send('toolbar.insert',{item,before});}
 const colors=['#57ad43','#48a5d2','#fac23d','#ed7154','#9c7bc0'];
 function pie(values){const total=values.reduce((a,b)=>a+b,0);if(total<=0||values.some(v=>v<0))return [];let start=-Math.PI/2;return values.map((value,i)=>{const end=start+value/total*Math.PI*2;const path=value===total?'M 180 35 A 90 90 0 1 1 179.99 35 Z':`M 180 125 L ${180+90*Math.cos(start)} ${125+90*Math.sin(start)} A 90 90 0 ${end-start>Math.PI?1:0} 1 ${180+90*Math.cos(end)} ${125+90*Math.sin(end)} Z`;start=end;return {path,color:colors[i%colors.length]};});}
 onMount(()=>{originalState=numbersState;originalWindow=window;originalRoot=root;originalProfile=profile;originalSession=w;const view=createNumbersNativeView({root,state: numbersState,profile,window,available:()=>current()&&available&&active&&!window.minimized});registerView(windowId,view);return ()=>{retired=true;view.destroy();registerView(windowId,null,view);};});
 const documentFonts=createDocumentFonts({getShared:name=>getShared(name),getFile:id=>getFile(id),getRoot:()=>root,getOwner:()=>[numbersState,profile,window,windowId,w]});
</script>
{#if w}
<section bind:this={root} class="numbers-app" class:numbers-classic={classic} class:numbers-high-sierra={highSierra} class:numbers-gold={gold} class:numbers-windows={cap.windows} aria-label={cap.label} onkeydown={keyboard} role="application" tabindex="-1">
 <header class="numbers-titlebar">
  {#if !cap.windows}<WindowControls {active} onclose={()=>send('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}
  <span class="numbers-document-icon">▥</span><strong>{d?.content.title??'Choose a Template'}</strong>{#if d&&d.revision!==d.savedRevision}<span class="numbers-edited">— Edited</span>{/if}
  {#if cap.windows}<span class="numbers-local-label">Numbers Local Equivalent</span><button aria-label="Minimize" onclick={controls.onminimize}>−</button><button aria-label="Maximize" onclick={controls.onzoom}>□</button><button aria-label="Close" onclick={()=>send('window.close')}>×</button>{/if}
 </header>
 {#if cap.windows||showMenuBar}<nav class="numbers-menubar" aria-label="Application menus">{#each menus as m}<details><summary>{m.label}</summary><div role="menu">{#each m.children as item}<button role="menuitem" disabled={!item.enabled} onclick={()=>menu(item)}><span>{item.label}</span><small>{item.shortcut??''}</small></button>{/each}</div></details>{/each}</nav>{/if}
 {#if d}
 {#if w.toolbar.visible}
 <div class="numbers-toolbar" data-numbers-toolbar class:numbers-toolbar-icon-only={w.toolbar.mode==='icon-only'} role="toolbar" aria-label="Spreadsheet tools" ondragover={toolbarOver} ondrop={e=>toolbarDrop(e)}>
  {#each toolbarGroups as group}
   <div class="numbers-toolbar-group" draggable={w.dialog==='toolbar'} ondragstart={e=>toolbarDrag(e,group)} ondragover={toolbarOver} ondrop={e=>{e.stopPropagation();toolbarDrop(e,group);}}>
    {#each group==='format'?['format','organize']:[group] as item}
     {#if item==='zoom'}<label class="numbers-zoom"><select data-numbers-control="toolbar-zoom" aria-label="Zoom" value={w.zoom} onchange={e=>send('zoom',{zoom:Number(e.currentTarget.value)})}>{#each [25,50,75,100,125,150,200] as z}<option value={z}>{z}%</option>{/each}</select>{#if w.toolbar.mode==='icon-label'}<span>Zoom</span>{/if}</label>
     {:else}<button data-numbers-control={`toolbar-${item}`} aria-label={toolbarLabel(item)} title={toolbarLabel(item)} class:selected={w.panel===item} onclick={()=>toolbarAction(item)}><b>{toolbarIcons[item]}</b>{#if w.toolbar.mode==='icon-label'}<span>{toolbarLabel(item)}</span>{/if}</button>{/if}
    {/each}
   </div>
  {/each}
  {#if w.dialog==='toolbar'}<span class="numbers-toolbar-drop-end" ondragover={toolbarOver} ondrop={e=>{e.stopPropagation();toolbarDrop(e);}} role="presentation">Drag here</span>{/if}
 </div>
 {/if}
 <nav class="numbers-sheet-tabs" aria-label="Sheets"><button aria-label="Add sheet" onclick={()=>send('sheet.add')}>＋</button>{#each d.content.sheets as sh}<button class:selected={sh.id===w.sheetId} onclick={()=>send('sheet.select',{sheetId:sh.id})}>{sh.name}</button>{/each}</nav>
 <div class="numbers-formula-bar"><span class="numbers-address">{w.selection.anchor}{w.selection.anchor!==w.selection.focus?':'+w.selection.focus:''}</span><span class="numbers-fx">ƒx</span><input data-numbers-control="formula-bar" aria-label="Formula bar" value={w.editing?w.edit:table?.cells[w.selection.focus]?.input??''} oninput={e=>send('edit.input',{input:e.currentTarget.value})} onkeydown={editorKey}/><button aria-label="Accept formula" onclick={()=>send('edit.commit')}>✓</button><button aria-label="Cancel formula edit" onclick={()=>send('edit.cancel')}>×</button></div>
 <div class="numbers-workspace">
 <main class="numbers-sheet" data-numbers-control="sheet" tabindex="0" aria-label="Spreadsheet canvas">
  <div class="numbers-canvas" style:zoom={w.zoom/100}>
  {#each sheet.tables as t}
   <section class="numbers-table-block" class:active-table={t.id===w.tableId} style:margin-left={`${t.x}px`} aria-label={t.name}>
    <button class="numbers-table-name" onclick={()=>send('table.select',{tableId:t.id})}>{t.name}</button>
    <table class="numbers-table" role="grid" aria-label={t.name}><thead><tr><th></th>{#each Array.from({length:t.columns},(_,i)=>i+1) as col}<th>{columnName(col)}</th>{/each}</tr></thead><tbody>
    {#each numbersVisibleRows(d.content,t,evaluation) as row}<tr><th scope="row">{row}</th>{#each Array.from({length:t.columns},(_,i)=>i+1) as col}
     {@const address=columnName(col)+row}{@const format=t.cells[address]?.format??{}}{@const selected=t===table&&row>=selection.minRow&&row<=selection.maxRow&&col>=selection.minColumn&&col<=selection.maxColumn}
     <td class:selected class:formula-error={evaluation.sheets[t.id]?.[address]?.type==='error'} style:font-family={documentFonts.css(format.fontFamily??'Helvetica Neue',format.bold,format.italic)} style:font-size={`${format.fontSize??12}px`} style:font-weight={format.bold?'700':'400'} style:font-style={format.italic?'italic':'normal'} style:color={format.color??'#292929'} style:background-color={format.fill??(row===1?'#e7e7e7':'#ffffff')}>
      {#if t===table&&w.editing&&w.selection.focus===address}<input class="numbers-cell-editor" data-numbers-control="cell-editor" aria-label={`Edit ${t.name} ${address}`} value={w.edit} oninput={e=>send('edit.input',{input:e.currentTarget.value})} onkeydown={editorKey}/>{:else}<button aria-label={`${t.name} ${address}: ${numbersCellText(d.content,t,address,evaluation)}`} aria-selected={selected} title={t.cells[address]?.input??''} onclick={e=>cellClick(t,address,e)} ondblclick={e=>cellEdit(t,address,e)}>{numbersCellText(d.content,t,address,evaluation)||'\u00a0'}</button>{/if}
     </td>
    {/each}</tr>{/each}
    </tbody></table>
    {#each t.charts as ch}
     {@const data=numbersChart(d.content,t,ch,evaluation)}{@const maximum=Math.max(1,...data.series.flatMap(s=>s.values.map(Math.abs)))}
     <figure class="numbers-chart"><figcaption>{ch.title}<button aria-label="Delete chart" onclick={async()=>{if(t!==table)await send('table.select',{tableId:t.id});await send('chart.delete',{chartId:ch.id});}}>×</button></figcaption>
      {#if data.errors.length}<p role="alert">Chart source error: {data.errors.join(', ')}</p>{:else if !data.series.length}<p>Select a range containing labels and numeric data.</p>{:else if ch.type==='pie'&&!pie(data.series[0].values).length}<p role="alert">Pie chart requires nonnegative values with a positive total.</p>{:else}
       <svg viewBox="0 0 460 280" role="img" aria-label={`${ch.type} chart: ${data.labels.map((label,i)=>label+': '+data.series.map(s=>s.values[i]).join(', ')).join('; ')}`}>
        {#if ch.type==='pie'}{#each pie(data.series[0].values) as sector}<path d={sector.path} fill={sector.color} stroke="white" stroke-width="1"/>{/each}{:else}
         <line x1="40" y1="140" x2="435" y2="140" stroke="#bbb"/>
         {#each data.series as series,index}
          {#if ch.type==='line'}<polyline points={series.values.map((v,i)=>`${50+i*370/Math.max(1,series.values.length-1)},${140-v/maximum*95}`).join(' ')} fill="none" stroke={colors[index%colors.length]} stroke-width="3"/>{:else}
           {#each series.values as value,i}<rect x={45+i*380/Math.max(1,data.labels.length)+index*350/Math.max(1,data.labels.length)/data.series.length} y={Math.min(140,140-value/maximum*95)} width={Math.max(1,Math.min(26,330/Math.max(1,data.labels.length)/data.series.length))} height={Math.abs(value)/maximum*95} fill={colors[index%colors.length]}/>{/each}
          {/if}
         {/each}
        {/if}
        {#each data.labels as label,i}<text x={ch.type==='pie'?305:50+i*370/Math.max(1,data.labels.length-1)} y={ch.type==='pie'?50+i*19:245} font-size="10" fill="#555">{label}</text>{/each}
       </svg><div class="numbers-chart-legend">{#each data.series as series,i}<span><i style:background={colors[i%colors.length]}></i>{series.name}</span>{/each}</div>
      {/if}<small>{ch.range} · live evaluated cells</small>
     </figure>
    {/each}
   </section>
  {/each}
  </div>
 </main>
 {#if w.panel!=='none'&&table}<aside class="numbers-inspector" aria-label={w.panel==='format'?'Format inspector':'Organize inspector'}>
  <div class="numbers-inspector-tabs"><button class:selected={w.panel==='format'} onclick={()=>send('panel',{panel:'format'})}>Format</button><button class:selected={w.panel==='organize'} onclick={()=>send('panel',{panel:'organize'})}>{highSierra?'Sort & Filter':'Organize'}</button></div>
  {#if w.panel==='format'}
   <h3>Document</h3><label>Title<input maxlength="128" value={d.content.title} onchange={e=>send('rename',{title:e.currentTarget.value})}/></label>
   <h3>Table</h3><label>Table Name<input maxlength="13" value={table.name} onchange={e=>send('table.rename',{name:e.currentTarget.value})}/></label>
   <div class="numbers-style-swatches">{#each ['#dcead8','#dbeaf4','#f9ead0','#e7e7e7'] as fill}<button aria-label={`Cell fill ${fill}`} style:background={fill} onclick={()=>send('format',{fill})}><span>Header</span><span>Table</span></button>{/each}</div>
   <h3>Cell</h3><label>Data Format<select value={selectedFormat.numberFormat??'general'} onchange={e=>send('format',{numberFormat:e.currentTarget.value})}>{#each ['general','number','currency','percent','date'] as f}<option value={f}>{f[0].toUpperCase()+f.slice(1)}</option>{/each}</select></label>
   <h3>Text</h3><label>Font<select data-numbers-control="font-family" aria-label="Font family" value={selectedFormat.fontFamily??'Helvetica Neue'} onchange={e=>send('format',{fontFamily:e.currentTarget.value})}>{#if !documentFonts.has(selectedFormat.fontFamily??'Helvetica Neue')}<option value={selectedFormat.fontFamily??'Helvetica Neue'} disabled>{selectedFormat.fontFamily??'Helvetica Neue'} (unavailable)</option>{/if}{#each documentFonts.families as f}<option>{f}</option>{/each}</select></label>
   <div class="numbers-inline"><input aria-label="Font size" type="number" min="8" max="72" value={selectedFormat.fontSize??12} onchange={e=>send('format',{fontSize:Number(e.currentTarget.value)})}/><button class:selected={selectedFormat.bold} onclick={()=>send('format',{bold:!selectedFormat.bold})}><b>B</b></button><button class:selected={selectedFormat.italic} onclick={()=>send('format',{italic:!selectedFormat.italic})}><i>I</i></button><input aria-label="Text color" type="color" value={selectedFormat.color??'#292929'} onchange={e=>send('format',{color:e.currentTarget.value})}/></div>
   <label>Cell Fill<input type="color" value={selectedFormat.fill??'#ffffff'} onchange={e=>send('format',{fill:e.currentTarget.value})}/></label>
   <h3>Rows & Columns</h3><div class="numbers-inline"><label>Rows<input type="number" min="1" max="512" value={table.rows} onchange={e=>send('table.size',{rows:Number(e.currentTarget.value),columns:table.columns})}/></label><label>Columns<input type="number" min="1" max="64" value={table.columns} onchange={e=>send('table.size',{rows:table.rows,columns:Number(e.currentTarget.value)})}/></label></div>
   <h3>Chart</h3><label>Type<select bind:value={chartType}><option value="bar">Column</option><option value="line">Line</option><option value="pie">Pie</option></select></label><label>Data Range<input bind:value={chartRange} maxlength="32"/></label><button onclick={()=>send('chart.add',{type:chartType,range:chartRange,title:'Chart'})}>Add Chart</button>
  {:else}
   <h3>Sort</h3><label>Column<select bind:value={sortColumn}>{#each Array.from({length:table.columns},(_,i)=>i+1) as c}<option value={c}>{columnName(c)}</option>{/each}</select></label><div class="numbers-inline"><button onclick={()=>send('sort',{column:sortColumn,direction:'ascending'})}>Ascending</button><button onclick={()=>send('sort',{column:sortColumn,direction:'descending'})}>Descending</button></div>
   <h3>Filter</h3><label>Rule<select bind:value={filterOperator}><option value="contains">Text contains</option><option value="equals">Equals</option><option value="greater">Greater than</option><option value="less">Less than</option></select></label><label>Value<input bind:value={filterValue} maxlength="256"/></label><button onclick={()=>send('filter',{enabled:true,column:sortColumn,operator:filterOperator,value:filterValue})}>Add Filter</button><button disabled={!table.filter} onclick={()=>send('filter',{enabled:false,column:sortColumn,operator:filterOperator,value:filterValue})}>Clear Filter</button><p>{table.filter?'Filtering '+columnName(table.filter.column)+' '+table.filter.operator+' '+table.filter.value:'All rows shown'}</p>
   <h3>Sheet</h3><label>Name<input maxlength="13" value={sheet.name} onchange={e=>send('sheet.rename',{name:e.currentTarget.value})}/></label><button disabled={d.content.sheets.length===1} onclick={()=>send('sheet.delete')}>Delete Sheet</button><button disabled={sheet.tables.length===1} onclick={()=>send('table.delete')}>Delete Table</button>
  {/if}
 </aside>{/if}
 </div>
 <footer class="numbers-status"><span role="status">{documentFonts.error||message||w.message||`${table.name} · ${w.selection.focus}`}</span><button onclick={()=>{saveName=d.content.title+'.xlsx';send('dialog',{dialog:'save'});}}>Save</button><button onclick={()=>{saveName=d.content.title+'.xlsx';send('dialog',{dialog:'export'});}}>Export…</button><button onclick={()=>send('print')}>Print…</button><button onclick={()=>send('dialog',{dialog:'help'})}>?</button></footer>
 {/if}
 {#if w.dialog==='templates'}
 <section class="numbers-chooser" role="dialog" aria-label="Choose a Template">
  <aside>{#each ['All Templates','Basic','Personal Finance','Business'] as cat}<button class:selected={category===cat} onclick={()=>category=cat}><span>▦</span>{cat}</button>{/each}<small>English (United States)</small></aside>
  <main><h1>Choose a Template</h1>{#each NUMBERS_TEMPLATES.filter(t=>category==='All Templates'||t.category===category) as template}<div class="numbers-template-group"><h2>{template.category}</h2><button class="numbers-template" data-numbers-control={`template-${template.id}`} onclick={()=>send('template',{template:template.id})}><div class="numbers-template-preview" class:budget={template.id==='budget'} class:invoice={template.id==='invoice'}>{#if template.id==='budget'}<div class="numbers-mini-chart"><i></i><i></i><i></i></div>{/if}{#if template.id==='invoice'}<strong>INVOICE</strong>{/if}<div class="numbers-mini-grid"></div></div><span>{template.name}</span></button><p>{template.description}</p></div>{/each}</main>
  <footer><span>Genuine XLSX / CSV · .numbers packages unavailable</span><button onclick={()=>send('open')}>Open…</button>{#if d}<button onclick={()=>send('dialog',{dialog:'none'})}>Cancel</button>{/if}</footer>
 </section>
 {:else if w.dialog==='toolbar'}
 <div class="numbers-sheet-shade numbers-toolbar-shade" style:top={`${(cap.windows?62:31+(showMenuBar?27:0))+(w.toolbar.mode==='icon-only'?42:61)}px`}><section class="numbers-document-sheet numbers-toolbar-sheet" role="dialog" aria-modal="true" aria-label="Customize Toolbar">
  <h2>Customize Toolbar</h2><p>Drag these supported controls to the toolbar above. Drag toolbar controls to reorder them, or to the removal area below. Format and {highSierra?'Sort & Filter':'Organize'} move together.</p>
  <div class="numbers-toolbar-palette">{#each NUMBERS_TOOLBAR_GROUPS as item}<div draggable="true" ondragstart={e=>toolbarDrag(e,item)} class:included={w.toolbar.items.includes(item)}><b>{toolbarIcons[item]}</b><span>{item==='format'?'Format & '+toolbarLabel('organize'):toolbarLabel(item)}</span><button data-numbers-control={`toolbar-add-${item}`} disabled={w.toolbar.items.includes(item)} onclick={()=>send('toolbar.insert',{item,before:null})}>Add</button></div>{/each}</div>
  <h3>Current Toolbar Order</h3><div class="numbers-toolbar-order">{#each toolbarGroups as item,index}<div><span>{item==='format'?'Format & '+toolbarLabel('organize'):toolbarLabel(item)}</span><button aria-label={`Move ${toolbarLabel(item)} left`} disabled={index===0} onclick={()=>toolbarMove(item,-1)}>←</button><button aria-label={`Move ${toolbarLabel(item)} right`} disabled={index===toolbarGroups.length-1} onclick={()=>toolbarMove(item,1)}>→</button><button aria-label={`Remove ${toolbarLabel(item)}`} onclick={()=>send('toolbar.remove',{item})}>Remove</button></div>{/each}</div>
  <div class="numbers-toolbar-remove" role="presentation" ondragover={toolbarOver} ondrop={e=>toolbarDrop(e,null,true)}>Drag toolbar items here to remove them</div>
  <label>Show<select data-numbers-control="toolbar-label-mode" value={w.toolbar.mode} onchange={e=>send('toolbar.configure',{mode:e.currentTarget.value})}><option value="icon-label">Icon and Text</option><option value="icon-only">Icon Only</option></select></label>
  <div class="numbers-toolbar-default-set" draggable="true" ondragstart={e=>toolbarDrag(e,'default-set')}><div>{#each NUMBERS_TOOLBAR_GROUPS as item}<span>{toolbarIcons[item]}</span>{/each}</div><small>Drag the default set into the toolbar</small></div>
  <div class="numbers-dialog-actions"><button data-numbers-control="toolbar-reset" onclick={()=>send('toolbar.reset')}>Restore Default Set</button><button class="numbers-primary" data-numbers-control="toolbar-done" onclick={()=>send('dialog',{dialog:'none'})}>Done</button></div><p role="alert">{message}</p>
 </section></div>
 {:else if w.dialog==='save'||w.dialog==='export'}
 <div class="numbers-sheet-shade"><form class="numbers-document-sheet" onsubmit={e=>{e.preventDefault();send(w.dialog==='save'?'save':'export',w.dialog==='save'?{name:saveName,saveAs:true}:{format:exportFormat,name:saveName});}}><h2>{w.dialog==='save'?'Save Spreadsheet':'Export Your Spreadsheet'}</h2><p>Native .numbers IWA packages are unavailable. XLSX exports each sheet/table as a real Excel worksheet named “Sheet · Table”.</p>{#if w.dialog==='export'}<label>Format<select bind:value={exportFormat} onchange={e=>saveName=d.content.title+'.'+e.currentTarget.value}><option value="xlsx">Excel (.xlsx)</option><option value="csv">CSV — selected table, evaluated values</option><option value="pdf">PDF — all tables and charts</option></select></label>{/if}<label>Save As<input bind:value={saveName} maxlength="256" required/></label><p>Where: Shared Documents</p><div class="numbers-dialog-actions"><button type="button" onclick={()=>send('dialog',{dialog:'none'})}>Cancel</button><button class="numbers-primary" type="submit">{w.dialog==='save'?'Save':'Export'}</button></div><p role="alert">{message}</p></form></div>
 {:else if w.dialog==='help'}
 <div class="numbers-sheet-shade"><section class="numbers-document-sheet" role="dialog" aria-label="Numbers Help"><h2>{cap.label}</h2><p>Installed font families are the original shared Font Book/Font Library sources, not proprietary Apple or Microsoft fonts. Enablement and source changes update this mounted document. Unavailable authored family names remain literal and use a safe browser rendering fallback; existing export font-embedding scopes are unchanged.</p><p>{cap.disclosure}</p><p>Click a cell to select; Shift-click extends a range. Double-click or press Return to edit. Formula bar accepts real formulas. Supported functions: SUM, AVERAGE, MIN, MAX, COUNT, IF; arithmetic, comparisons, strings, absolute references, and ranges. Cross-table references use the exported worksheet name: <code>='Sheet 1 · Table 1'!A1</code>.</p><p>The shared spreadsheet engine reports #CYCLE!, #DIV/0!, #NAME?, #REF!, #VALUE!, and #N/A; it never executes JavaScript. Charts update from evaluated ranges. CSV exports evaluated values from the selected table. XLSX carries formulas and charts; active filters must be cleared before export. PDF preserves all table cells, with a chart page for each chart.</p><p>No iCloud collaboration or proprietary Numbers format is claimed. Sharing and printing use the one shared Root destination.</p><button class="numbers-primary" onclick={()=>send('dialog',{dialog:d?'none':'templates'})}>Done</button></section></div>
 {/if}
</section>
{/if}
